-- Read-only hosted release audit. No account rows or secret values are read.
select jsonb_build_object(
 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'signature',p.oid::regprocedure::text,'config',p.proconfig,'anon',has_function_privilege('anon',p.oid,'execute'),'authenticated',has_function_privilege('authenticated',p.oid,'execute'),'service',has_function_privilege('service_role',p.oid,'execute'))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef),
 'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'rls',c.relrowsecurity,'anon',(has_table_privilege('anon',c.oid,'select,insert,update,delete,truncate') or has_any_column_privilege('anon',c.oid,'select,insert,update')),'user_read',has_any_column_privilege('authenticated',c.oid,'select'),'user_insert',has_any_column_privilege('authenticated',c.oid,'insert'),'user_update',has_any_column_privilege('authenticated',c.oid,'update'),'user_delete',has_table_privilege('authenticated',c.oid,'delete'),'user_truncate',has_table_privilege('authenticated',c.oid,'truncate'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind='r'),
 'profile_update_columns',(select jsonb_agg(a.attname) from pg_attribute a where a.attrelid='public.profiles'::regclass and a.attnum>0 and not a.attisdropped and has_column_privilege('authenticated',a.attrelid,a.attnum,'update')),
 'storage_policies',(select coalesce(jsonb_agg(jsonb_build_object('name',policyname,'command',cmd,'roles',roles)), '[]'::jsonb) from pg_policies where schemaname='storage' and tablename='objects'),
 'buckets',(select jsonb_agg(jsonb_build_object('id',id,'public',public)) from storage.buckets where id in ('group-media','profile-avatars'))
) as audit;
